import "jsr:@supabase/functions-js/edge-runtime.d.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const adminCode = Deno.env.get("CLB5H_ADMIN_CODE") || "111";
const table = "clb5h_events";

function json(data: unknown, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

async function databaseRequest(path: string, init: RequestInit = {}) {
  const response = await fetch(`${supabaseUrl}/rest/v1/${path}`, {
    ...init,
    headers: {
      apikey: serviceRoleKey,
      Authorization: `Bearer ${serviceRoleKey}`,
      "Content-Type": "application/json",
      Prefer: "return=representation",
      ...(init.headers || {}),
    },
  });
  const text = await response.text();
  let data: unknown = null;
  try {
    data = text ? JSON.parse(text) : null;
  } catch {
    data = { message: text };
  }
  if (!response.ok) throw new Error((data as { message?: string })?.message || "database-request-failed");
  return data;
}

function cleanEvent(item: Record<string, unknown>) {
  return {
    id: String(item.id || "").slice(0, 96),
    title: String(item.title || "").slice(0, 120),
    event_date: String(item.date || "").slice(0, 120),
    month: String(item.month || "").slice(0, 7),
    description: String(item.description || "").slice(0, 4000),
    status: item.status === "ended" ? "ended" : item.status === "hidden" ? "hidden" : "active",
  };
}

function eventId(item: Record<string, unknown>) {
  return encodeURIComponent(String(item.id || ""));
}

Deno.serve(async (request) => {
  if (request.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
  if (request.method !== "POST") return json({ error: "method-not-allowed" }, 405);

  try {
    const body = await request.json();
    if (String(body.code || "") !== adminCode) return json({ error: "invalid-admin-code" }, 401);

    const action = String(body.action || "");
    const item = (body.item || {}) as Record<string, unknown>;
    if (action === "create") {
      const clean = cleanEvent(item);
      if (!clean.id || !clean.title || !clean.description) return json({ error: "invalid-event" }, 400);
      return json(await databaseRequest(table, { method: "POST", body: JSON.stringify(clean) }));
    }
    if (action === "update") {
      const id = eventId(item);
      if (!id) return json({ error: "missing-id" }, 400);
      const clean = cleanEvent(item);
      if (!clean.title || !clean.description) return json({ error: "invalid-event" }, 400);
      return json(await databaseRequest(`${table}?id=eq.${id}`, { method: "PATCH", body: JSON.stringify(clean) }));
    }
    if (action === "toggle") {
      const id = eventId(item);
      if (!id) return json({ error: "missing-id" }, 400);
      const status = item.status === "hidden" ? "active" : "hidden";
      return json(await databaseRequest(`${table}?id=eq.${id}`, { method: "PATCH", body: JSON.stringify({ status }) }));
    }
    if (action === "delete") {
      const id = eventId(item);
      if (!id) return json({ error: "missing-id" }, 400);
      return json(await databaseRequest(`${table}?id=eq.${id}`, { method: "PATCH", body: JSON.stringify({ deleted_at: new Date().toISOString() }) }));
    }
    if (action === "restore") {
      const id = eventId(item);
      if (!id) return json({ error: "missing-id" }, 400);
      return json(await databaseRequest(`${table}?id=eq.${id}`, { method: "PATCH", body: JSON.stringify({ deleted_at: null }) }));
    }
    if (action === "permanentDelete") {
      const id = eventId(item);
      if (!id) return json({ error: "missing-id" }, 400);
      return json(await databaseRequest(`${table}?id=eq.${id}`, { method: "DELETE" }));
    }
    return json({ error: "unknown-action" }, 400);
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : "unexpected-error" }, 500);
  }
});
